// Service worker of the PWA build (docs/pwa-plan.md §6, phase 5). The worker itself is generated by vite-plugin-pwa
// (Workbox) and precaches the app shell. This module registers it and runs the update flow:
//
//   - first visit: the worker installs and takes control, so the next start works offline;
//   - a new version: it installs in the background and WAITS. The app shows "New version available · Reload";
//     only a tap on Reload activates it and reloads the page (never in the middle of planning).
//
// Only the PWA production build registers a worker. The desktop build and `npm run dev:pwa` never do.
import { Workbox } from 'workbox-window';

export interface UpdateHooks {
  /** a new version is waiting */
  onUpdateReady: () => void;
}

/**
 * Registers /sw.js and returns the function that activates a waiting version and reloads. Returns null when no
 * worker is registered.
 */
export function registerServiceWorker(hooks: UpdateHooks, url = '/sw.js'): (() => void) | null {
  const wb = new Workbox(url, { scope: '/' });
  let reloading = false;

  wb.addEventListener('waiting', () => hooks.onUpdateReady());
  // after the user tapped Reload: the new worker controls the page now → load the new version
  wb.addEventListener('controlling', (e) => {
    if (e.isUpdate && reloading) location.reload();
  });

  wb.register().catch((err: unknown) => console.warn('[sw] registration failed', err));

  // look for a new version when the app comes back to the front (iOS keeps home screen apps alive for days)
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') void wb.update().catch(() => {});
  });

  return () => {
    reloading = true;
    wb.messageSkipWaiting();
    // if the worker is already active (e.g. another tab activated it), just reload
    setTimeout(() => location.reload(), 3000);
  };
}
